#!/usr/bin/env bash
# =============================================================================
# PARROTO - seed the free public "Từ vựng B2 thiết yếu" deck into vocabulary_db.
# Runs after 01-init.sql (schema + base seed) on the FIRST start of an empty volume.
# The SQL is generated by scripts/gen-b2-seed.py and is idempotent.
# =============================================================================
set -euo pipefail
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname vocabulary_db \
  -f /docker-entrypoint-initdb.d/seed/002_seed_b2_deck.sql
